import { sql } from "drizzle-orm";
import { date, pgEnum, timestamp, uuid } from "drizzle-orm/pg-core";
import * as E from "../../../lib/enums.js";

// Conventions from docs/ARCHITECTURE.md §2.1. Column names come from the JS keys via
// casing: 'snake_case' (set on the client and in drizzle.config.js).

/** Primary key: time-ordered UUID generated by Postgres 18. */
export const id = () =>
  uuid()
    .primaryKey()
    .default(sql`uuidv7()`);

/** Date-only value, read and written as 'YYYY-MM-DD'. Never a JS Date. */
export const day = () => date({ mode: "string" });

/** An instant in time, stored as timestamptz (UTC). */
export const instant = () => timestamp({ withTimezone: true });

/** created_at / updated_at for mutable tables. Fresh builders per table. */
export const timestamps = () => ({
  createdAt: instant().notNull().defaultNow(),
  updatedAt: instant()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

